    requires n >= 0
    ensures result == fib4(n)
{
    var a, b, c, d := 0, 0, 2, 0;
    if n == 0 {
        return a;
    } else if n == 1 {
        return b;
    } else if n == 2 {
        return c;
    } else if n == 3 {
        return d;
    }

    var temp := 0;
    var i := 4;
    while i <= n
        invariant 0 <= i <= n + 1
        invariant a == fib4(i - 4)
        invariant b == fib4(i - 3)
        invariant c == fib4(i - 2)
        invariant d == fib4(i - 1)
    {
        temp := a + b + c + d;
        a := b;
        b := c;
        c := d;
        d := temp;
        i := i + 1;
    }

    return d;
}

